const body = $input.first().json.body || $input.first().json;
const phone = (body.phone || '5511999999999').replace(/\D/g, '');
const name = body.name || body.pushName || 'Paciente';
const text = (body.text || body.message || '').trim().toLowerCase();

// Verificação ética imediata
if (text.includes('suicidio') || text.includes('me matar') || text.includes('desespero')) {
  return [{
    json: {
      phone,
      isEmergency: true,
      reply: `Olá ${name}. Percebemos que você está passando por grande sofrimento. Por favor, ligue imediatamente para o 188 (CVV - Centro de Valorização da Vida). É gratuito, sigiloso e 24h.`
    }
  }];
}

// Menu de Triagem Inicial
const reply = `Olá, ${name}! Sou a assistente virtual da Clínica Serenidade.\n\nFico muito feliz pelo seu contato para cuidar da sua saúde mental.\n\nPara iniciarmos, você prefere:\n1️⃣ Terapia *Online* (no conforto da sua casa via link seguro)\n2️⃣ Terapia *Presencial* (Av. Paulista, São Paulo)\n\nDigite 1 ou 2 para vermos a disponibilidade.`;

return [{
  json: {
    phone,
    name,
    isEmergency: false,
    reply
  }
}];
